package com.example.workout.shoe.entity; import jakarta.persistence.*; import java.time.*; import lombok.*; @Entity @Table(name="running_shoes") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder(setterPrefix="with") public class RunningShoeEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=100) private String brand; @Column(nullable=false,length=150) private String model; @Column(length=100) private String nickname; private LocalDate purchaseDate; @Column(nullable=false) private Long initialDistanceMeters; @Column(nullable=false) private Boolean active; @Column(length=1000) private String notes; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; }
